async function resumeRebuild(carId){const existing=await api('plan','rebuild.draft',{carId});return existing?.id||await change('rebuild.start',{carId,revision:db.revision});}
function rebuildAssignments(){
 const p=buildState?.rebuild,m=db._view?.rebuild;if(!p||!m)return [];
 return [...m.installations.filter(i=>p.reuse.includes(i.id)),...db.assemblies.filter(a=>p.assemblies.includes(a.id)&&a.carId===p.carId).flatMap(a=>a.components.map(c=>({...c,name:db.parts.find(x=>x.id===c.partId)?.name,assemblyName:a.name})))].map(i=>({...i,slot:BuildModel.slots.find(s=>s.field&&s.field===i.field)?.id||'',reuse:true}));
}
function effectiveBuildState(){return {...buildState,parts:[...buildState.parts,...rebuildAssignments()]};}
function renderRebuildLinks(c){
 if(!local()||!c.rebuild)return '';
 return ['to','from'].filter(k=>c.rebuild[k]).map(kind=>{const edge=c.rebuild[kind],live=db._view?.rebuildLinks?.[kind]||db.cars.find(x=>x.id===edge.id),next=kind==='to';return `<section class="panel rebuild-link ${next?'rebuild-successor':''}"><div class="rebuild-link-kicker">${icon('tool')}${next?'A new chapter':'The story so far'}</div><h2>${next?'Rebuilt as':'Rebuilt from'}</h2><div class="rebuild-link-identity"><div class="rebuild-link-photo">${live?.picture?`<img src="${esc(thumbnailSource(live.picture))}" alt="" loading="lazy">`:icon('car')}</div><div><strong>${esc(live?.name||edge.name)}</strong><p class="tiny muted">${date(edge.date)}</p></div></div><p class="muted">${next?'This original keeps its history. Future work and races belong to the rebuilt car.':'Earlier setups, photos and race results remain with the original car.'}</p>${btn((next?'View rebuilt car':'View original car')+' '+icon('next'),'rebuild-open','',edge.id)}</section>`;}).join('');
}
function renderRebuildEditor(){
 const p=buildState?.rebuild;if(!p)return '';const m=db._view?.rebuild;
 const rows=(items,key)=>items.map(i=>`<label class="rebuild-reuse"><input type="checkbox" data-rebuild-reuse="${key}" value="${esc(i.id)}" ${p[key].includes(i.id)?'checked':''}><span><strong>${esc(i.name)}</strong><small>${i.quantity||i.pieces} piece(s)${i.position?' · '+esc(i.position):''}</small></span></label>`).join('');
 return `<section class="panel rebuild-planner"><div class="section-heading"><div><span class="rebuild-link-kicker">${icon('tool')}Rebuild project</span><h2>${esc(m?.name||'Original car')}</h2></div>${btn('Refresh original…','rebuild-refresh')}${btn('Open workshop job','open-job','',p.jobId)}</div><p class="muted">Choose fitted parts to carry over. Add replacements using the diagram below. Unselected fitted parts return to used stock only when you complete the rebuild.</p>${m&&m.carRevision!==p.carRevision?'<p class="note">The original changed. Refresh it and review your choices before completing.</p>':''}<div class="rebuild-reuse-grid">${m?rows(m.installations,'reuse')+rows(m.assemblies,'assemblies'):'<p>Loading original components…</p>'}</div>${m&&!m.installations.length&&!m.assemblies.length?'<p class="muted">No tracked parts fitted. Plan stock or catalogue parts below.</p>':''}<div class="actions mt"><label class="check-row"><input type="checkbox" data-rebuild-option="carrySpecifications" ${p.carrySpecifications?'checked':''}>Carry over untracked specifications</label><label class="check-row"><input type="checkbox" data-rebuild-option="copyPhoto" ${p.copyPhoto?'checked':''}>Use the original main photo</label></div><p class="tiny muted">Selected parts cannot share a technical position with a replacement. The original remains unchanged until completion. Save the plan to keep your choices and update shopping; cancel the project from its Workshop job.</p></section>`;
}
async function openRebuildDraft(id){
 const d=id&&await api('plan','build.draft',{id});if(!d){throw Error('This rebuild draft no longer exists. Reopen the Workshop job.');}
 buildState=structuredClone(d.data);buildContext=db.id;buildDraftId=d.id;buildDirty=false;page='Build from Scratch';carId=null;buildSlot='motor';buildSearch='';buildAll=false;$('#dialog').close();render();
}
function startRebuildDialog(id){
 const cars=db.cars.filter(c=>!c.archived),revision=db.revision;if(!cars.length)throw Error('Add an active car before starting a rebuild.');
 modal('Start a rebuild',`<p>Keep the original car’s history and plan a new, linked configuration.</p><label class="field">Original car<select name="carId" required>${cars.map(c=>`<option value="${esc(c.id)}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><p class="note info mt">Starting creates a Workshop job and a saved build draft. No car or inventory changes until completion.</p>${buildDirty?'<p class="note">Opening this rebuild will replace your unsaved builder selections. Cancel and save your current draft first if you want to keep them.</p>':''}`,async values=>{const draft=await change('rebuild.start',{carId:values.carId,revision});await openRebuildDraft(draft);},'Start rebuild');
}
function rebuildJobCard(j){if(j.category!=='rebuild'||j.kind!=='general')return '';const c=db.cars.find(c=>c.id===j.carId);if(j.status==='active')return `<section class="panel rebuild-planner"><h2>${icon('tool')}Build the next chapter</h2><p class="muted">Choose reused parts and replacements in Build from Scratch. Completing the rebuild preserves this car and creates its linked successor.</p>${btn('Open rebuild editor','rebuild-resume','primary',j.carId)}</section>`;return c?.rebuild?.to?renderRebuildLinks(c):'';}
async function rebuildAction(action,id){
 if(['add-work','add-test','save-setup','new-job','maintenance-job'].includes(action)){const c=db.cars.find(c=>c.id===(id||carId));if(c?.rebuild?.to){modal('Continue with the rebuilt car',`<p>${esc(c.name)} is a preserved historical record.</p>${btn('Open '+esc(c.rebuild.to.name),'rebuild-open','primary',c.rebuild.to.id)}`,null);return true;}}
 if(!action.startsWith('rebuild-'))return false;if(!local())return true;
 if(action==='rebuild-start'){startRebuildDialog(id);return true;}
 if(action==='rebuild-resume'){if(buildDirty){modal('Open rebuild editor?','<p>Your unsaved builder choices will be replaced. Cancel and save your current draft first to keep them.</p>',async()=>openRebuildDraft(await resumeRebuild(id)),'Open rebuild');}else await openRebuildDraft(await resumeRebuild(id));return true;}
 if(action==='rebuild-open'){page='Cars';carId=id;section='Overview';$('#dialog').close();render();return true;}
 if(action==='rebuild-refresh'){const m=await api('plan','rebuild.context',{carId:buildState.rebuild.carId});if(m.rebuilt||m.archived)throw Error('This original is already rebuilt or archived. Open its car page.');modal('Refresh original configuration',`<p>Use the latest configuration of <strong>${esc(m.name)}</strong>. Missing reused parts will be deselected; review the remaining choices.</p>`,async()=>{const p=buildState.rebuild;p.carRevision=m.carRevision;p.reuse=p.reuse.filter(id=>m.installations.some(i=>i.id===id));p.assemblies=p.assemblies.filter(id=>m.assemblies.some(a=>a.id===id));const latest=await readScreen();acceptSnapshot(latest.data);markBuildDirty();},'Refresh original');return true;}
 return true;
}
document.addEventListener('change',event=>{const el=event.target,p=buildState?.rebuild;if(!p)return;if(el.dataset.rebuildReuse){const key=el.dataset.rebuildReuse;p[key]=el.checked?[...new Set([...p[key],el.value])]:p[key].filter(id=>id!==el.value);markBuildDirty();buildRefresh();}if(el.dataset.rebuildOption){p[el.dataset.rebuildOption]=el.checked;markBuildDirty();}});
